using System;using System.IO;using System.Reflection;using System.Collections.Generic;using System.Diagnostics;using System.Threading;using System.Security.Cryptography;using System.Web.Script.Serialization;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Media.Imaging;
public static class IndicatorReview {
 static BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public;static object Get(object o,string n){return o.GetType().GetField(n,F).GetValue(o);}static object Prop(object o,string n){return o.GetType().GetProperty(n,F).GetValue(o,null);}static object Call(object o,string n,params object[] args){return o.GetType().GetMethod(n,F).Invoke(o,args);}static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
 [STAThread]public static int Main(string[] args){var report=new Dictionary<string,object>();Window window=null;object smooth=null;string folder=Path.GetFullPath(args[1]);Directory.CreateDirectory(folder);try{
  using(var h=SHA256.Create())using(var s=File.OpenRead(args[0]))report["candidate_sha256"]=BitConverter.ToString(h.ComputeHash(s)).Replace("-","").ToLowerInvariant();var a=Assembly.LoadFrom(Path.GetFullPath(args[0]));var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};window=(Window)Activator.CreateInstance(a.GetType("WhiteDragon.PetWindow"),new object[]{true});window.Opacity=0;window.ShowActivated=false;window.Show();smooth=Get(window,"smooth");var behavior=Get(window,"behavior");var indicator=Get(window,"thinkingIndicator");var layer=(Canvas)Get(indicator,"Layer");var clock=(Stopwatch)Get(window,"clock");
  Call(smooth,"EnsureSample",18,0.0,10000);Thread.Sleep(130);Call(window,"Choose",18);for(int i=0;i<16;i++){Thread.Sleep(20);Call(window,"RenderFrame");}double start=(double)Prop(indicator,"Angle");Thread.Sleep(80);Call(window,"RenderFrame");Check((double)Prop(indicator,"Angle")!=start&&layer.Opacity>.95,"Visible thinking circle must rotate");Check(!layer.IsHitTestVisible,"Circle must not intercept pet dragging");
  var canvas=(Canvas)Get(window,"canvas");canvas.Measure(new Size(window.Width,window.Height));canvas.Arrange(new Rect(0,0,window.Width,window.Height));canvas.UpdateLayout();var image=new RenderTargetBitmap((int)Math.Ceiling(window.Width),(int)Math.Ceiling(window.Height),96,96,PixelFormats.Pbgra32);image.Render(canvas);using(var s=File.Create(Path.Combine(folder,"thinking-spinner.png"))){var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(image));encoder.Save(s);}
  foreach(string mode in new string[]{"SetPaused","SetMenu"}){Call(behavior,mode,true,clock.ElapsedMilliseconds);Call(window,"RenderFrame");double frozen=(double)Prop(indicator,"Angle");Thread.Sleep(110);Call(window,"RenderFrame");Check((double)Prop(indicator,"Angle")==frozen,"Circle changes during "+mode);Call(behavior,mode,false,clock.ElapsedMilliseconds);Call(window,"RenderFrame");}report["pause_and_menu_freeze"]=true;
  Call(smooth,"EnsureSample",19,0.0,10000);Thread.Sleep(120);Call(window,"Choose",19);for(int i=0;i<18;i++){Thread.Sleep(20);Call(window,"RenderFrame");}Check(layer.Opacity==0&&layer.Visibility==Visibility.Collapsed,"Circle must fade away outside thinking");report["fades_out_on_working"]=true;Check((double)Prop(Get(window,"stretch"),"ScaleX")==1&&(double)Prop(Get(window,"stretch"),"ScaleY")==1,"Body scaling changed");report["body_scale_unchanged"]=true;report["only_circle_rotates"]=true;report["ok"]=true;
 }catch(Exception e){report["ok"]=false;report["error"]=e.ToString();}finally{if(window!=null)window.Close();if(smooth!=null)report["worker_stopped"]=Prop(smooth,"WorkerStopped");File.WriteAllText(Path.Combine(folder,"indicator-review.json"),new JavaScriptSerializer().Serialize(report));}return (bool)report["ok"]?0:1;}
}
